import { Skeleton } from "@/components/ui/skeleton"

export default function Page() {
  return (
    <div className="flex flex-1 flex-col gap-4 p-4">
      <div className="grid auto-rows-min gap-4 md:grid-cols-3">
        <Skeleton className="aspect-video" />
        <Skeleton className="aspect-video" />
        <Skeleton className="aspect-video" />
      </div>
      <Skeleton className="min-h-screen flex-1 md:min-h-min" />
    </div>
  )
}

import type { CSSProperties, PropsWithChildren } from "react"
import { AppHeader } from "@/components/blocks/dashboard-01/components/app-header"
import { AppSidebar } from "@/components/blocks/dashboard-01/components/app-sidebar"
import { SidebarInset, SidebarProvider } from "@/components/ui/sidebar"

export default function Layout({ children }: PropsWithChildren) {
  return (
    <SidebarProvider
      style={
        {
          "--sidebar-width": "calc(var(--spacing) * 72)",
          "--header-height": "calc(var(--spacing) * 12)"
        } as CSSProperties
      }
    >
      <AppSidebar />
      <SidebarInset>
        <AppHeader />
        {children}
      </SidebarInset>
    </SidebarProvider>
  )
}

"use client"

import type { ComponentPropsWithoutRef } from "react"
import type { NavItem } from "./data"
import { Sidebar } from "@/components/ui/sidebar"

export function NavSecondary({
  items,
  ...props
}: {
  items: NavItem[]
} & ComponentPropsWithoutRef<typeof Sidebar.Group>) {
  return (
    <Sidebar.Group {...props}>
      <Sidebar.GroupContent>
        <Sidebar.Menu>
          {items.map((item) => (
            <Sidebar.MenuItem key={item.title}>
              <Sidebar.MenuButton href={item.url} isActive={item.isActive}>
                {item.icon && <item.icon />}
                <span>{item.title}</span>
              </Sidebar.MenuButton>
            </Sidebar.MenuItem>
          ))}
        </Sidebar.Menu>
      </Sidebar.GroupContent>
    </Sidebar.Group>
  )
}

"use client"
import { Breadcrumb } from "@/components/ui/breadcrumb"

export function AppBreadcrumbs() {
  return (
    <Breadcrumb>
      <Breadcrumb.Item href="#">Dashboard</Breadcrumb.Item>
      <Breadcrumb.Item href="#">Blocks</Breadcrumb.Item>
      <Breadcrumb.Item>Page</Breadcrumb.Item>
    </Breadcrumb>
  )
}
